const dt = 1 / 60; // Un segundo expresado en minutos
const capacidad = 3000;

// Recuperar el estado anterior o crear el inicial
let planta = flow.get("planta") || {
    nivel: 1500,
    caudal: 0,
    ph: 7.8,
    turbidez: 12,
    bomba: true,
    dosificacion: 50,
    descarga: false,
    tiempo: 0
};

// Protección automática del tanque
if (planta.nivel >= capacidad) {
    planta.bomba = false;
}

// Protección automática de calidad y nivel
if (
    planta.ph < 6.5 ||
    planta.ph > 8.5 ||
    planta.turbidez >= 5 ||
    planta.nivel <= 0
) {
    planta.descarga = false;
}

// Caudal de entrada según el estado de la bomba
planta.caudal = planta.bomba ? 40 : 0;

// Salida de agua del tanque
const salida = planta.descarga ? 25 : 0;

// Balance de volumen
planta.nivel += (planta.caudal - salida) * dt;
planta.nivel = Math.max(0, Math.min(capacidad, planta.nivel));

// Dosificación gradual del reactivo simulado
const dosis = planta.dosificacion / 100;
const turbidezObjetivo = 12 - 10 * dosis;
const phObjetivo = 7.8 - 1.2 * dosis;

// Respuesta gradual de las variables
planta.turbidez +=
    (turbidezObjetivo - planta.turbidez) * 0.01;

planta.ph +=
    (phObjetivo - planta.ph) * 0.005;

planta.tiempo += 1;

// Guardar el estado compartido
flow.set("planta", planta);

// Publicar telemetría
msg.payload = {
    dispositivo: "A09-Planta",
    timestamp: new Date().toISOString(),
    nivel: Number(planta.nivel.toFixed(2)),
    caudal: planta.caudal,
    ph: Number(planta.ph.toFixed(2)),
    turbidez: Number(planta.turbidez.toFixed(2)),
    bomba: planta.bomba,
    dosificacion: planta.dosificacion,
    descarga: planta.descarga
};

return msg;

let comando = msg.payload;

// Convertir JSON recibido
if (typeof comando === "string") {
    try {
        comando = JSON.parse(comando);
    } catch (error) {
        node.warn("JSON no válido");
        return null;
    }
}

if (!comando || typeof comando !== "object" ||
    Array.isArray(comando)) {
    return null;
}

// Recuperar estado de la planta
let planta = flow.get("planta");

if (!planta) {
    node.warn("Simulador todavía no inicializado");
    return null;
}

// Historial de comandos procesados
let procesados = context.get("comandosProcesados") || {};

// Identificar comando
const id = typeof comando.id === "string" &&
           comando.id.trim() !== ""
    ? comando.id
    : null;

// Detectar duplicados sin ejecutar nuevamente
if (id && procesados[id]) {
    msg.payload = {
        id: id,
        recibido: true,
        aceptado: procesados[id].aceptado,
        duplicado: true,
        accion: procesados[id].accion,
        valor: procesados[id].valor,
        motivo: "Comando duplicado: no se ejecutó nuevamente",
        timestamp: new Date().toISOString()
    };

    return msg;
}

let aceptado = false;
let motivo = "";

// Control de bomba
if (comando.accion === "bomba") {
    if (typeof comando.valor !== "boolean") {
        motivo = "Valor de bomba no válido";
    } else if (comando.valor && planta.nivel >= 3000) {
        motivo = "Tanque lleno. No se puede encender la bomba";
    } else {
        planta.bomba = comando.valor;
        aceptado = true;
    }
}

// Control de dosificación
else if (comando.accion === "dosificacion") {
    const valor = Number(comando.valor);

    if (!Number.isFinite(valor) || valor < 0 || valor > 100) {
        motivo = "Dosificación fuera de rango";
    } else {
        planta.dosificacion = valor;
        aceptado = true;
    }
}

// Control de descarga
else if (comando.accion === "descarga") {
    if (typeof comando.valor !== "boolean") {
        motivo = "Valor de descarga no válido";
    } else if (
        comando.valor &&
        (
            planta.ph < 6.5 ||
            planta.ph > 8.5 ||
            planta.turbidez >= 5 ||
            planta.nivel <= 0
        )
    ) {
        motivo = "Descarga bloqueada: calidad de agua o nivel inadecuado";
    } else {
        planta.descarga = comando.valor;
        aceptado = true;
    }
}

else {
    motivo = "Comando no reconocido";
}

// Guardar el estado si se aceptó
if (aceptado) {
    flow.set("planta", planta);
}

// Registrar identificador para evitar duplicados
if (id) {
    procesados[id] = {
        aceptado: aceptado,
        accion: comando.accion,
        valor: comando.valor
    };

    // Conservar únicamente los últimos 200 comandos
    const ids = Object.keys(procesados);

    if (ids.length > 200) {
        delete procesados[ids[0]];
    }

    context.set("comandosProcesados", procesados);
}

// Respuesta ACK
msg.payload = {
    id: id,
    recibido: true,
    aceptado: aceptado,
    duplicado: false,
    accion: comando.accion,
    valor: comando.valor,
    motivo: aceptado ? "Comando ejecutado" : motivo,
    timestamp: new Date().toISOString()
};

return msg;

const datos = msg.payload;
const ahora = new Date().toISOString();

const condiciones = [
    {
        codigo: "ALM-PH",
        mensaje: "pH fuera de rango",
        severidad: "Alta",
        activa: datos.ph < 6.5 || datos.ph > 8.5
    },
    {
        codigo: "ALM-TURB",
        mensaje: "Turbidez elevada",
        severidad: "Media",
        activa: datos.turbidez >= 5
    },
    {
        codigo: "ALM-NIVEL",
        mensaje: "Tanque lleno: riesgo de desbordamiento",
        severidad: "Critica",
        activa: datos.nivel >= 3000
    }
];

const anteriores = context.get("alarmasEstado") || {};
const eventos = [];

for (const alarma of condiciones) {
    const estabaActiva = anteriores[alarma.codigo] === true;

    if (alarma.activa !== estabaActiva) {
        eventos.push({
            dispositivo: "A09-Planta",
            codigo: alarma.codigo,
            mensaje: alarma.mensaje,
            severidad: alarma.severidad,
            estado: alarma.activa ? "ACTIVA" : "RECUPERADA",
            timestamp: ahora,
            reconocida: false
        });
    }

    anteriores[alarma.codigo] = alarma.activa;
}

context.set("alarmasEstado", anteriores);

if (eventos.length === 0) {
    return null;
}

msg.payload = {
    dispositivo: "A09-Planta",
    timestamp: ahora,
    eventos: eventos,
    total: eventos.length
};

return msg;

let comando = msg.payload;

if (typeof comando === "string") {
    try {
        comando = JSON.parse(comando);
    } catch (error) {
        node.warn("Comando JSON no válido");
        return null;
    }
}

if (!comando || typeof comando !== "object") {
    return null;
}

// Preparar el comando para el simulador
msg.payload = comando;
msg.topic = "control_planta_a09";

return msg;

let datos = msg.payload;

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        node.warn("Mensaje de alarma no válido");
        return null;
    }
}

if (!datos || !Array.isArray(datos.eventos)) {
    return null;
}

let historial = flow.get("historialAlarmas") || [];

for (const evento of datos.eventos) {
    historial.push({
        codigo: evento.codigo,
        mensaje: evento.mensaje,
        severidad: evento.severidad,
        estado: evento.estado,
        timestamp: evento.timestamp,
        reconocida: evento.reconocida === true
    });
}

// Conservar los últimos 200 eventos
if (historial.length > 200) {
    historial = historial.slice(-200);
}

flow.set("historialAlarmas", historial);

msg.payload = {
    eventosRecibidos: datos.eventos.length,
    totalRegistrados: historial.length,
    ultimoEvento: historial[historial.length - 1] || null
};

return msg;

let historial = flow.get("historialAlarmas") || [];

msg.payload = {
    total: historial.length,
    historial: historial
};

return msg;

const codigo = msg.payload.codigo;
let historial = flow.get("historialAlarmas") || [];

let encontrados = 0;

for (let evento of historial) {
    if (evento.codigo === codigo &&
        evento.reconocida === false) {
        evento.reconocida = true;
        evento.fechaReconocimiento =
            new Date().toISOString();
        encontrados++;
    }
}

flow.set("historialAlarmas", historial);

msg.payload = {
    codigo: codigo,
    reconocidos: encontrados,
    mensaje: encontrados > 0
        ? "Alarma reconocida correctamente"
        : "No hay alarmas pendientes de reconocimiento"
};

return msg;

let datos = msg.payload;

// Convertir JSON si llega como texto
if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        node.warn("KPI: JSON no válido");
        return null;
    }
}

// Validar datos recibidos
if (!datos || !Number.isFinite(Number(datos.nivel))) {
    node.warn("KPI: datos de planta no válidos");
    return null;
}

// Recuperar indicadores guardados
let kpi = context.get("kpi") || {
    volumenTratado: 0,
    tiempoEspecificacion: 0,
    consumoReactivo: 0,
    tiempoProceso: 0,
    tiempoDisponible: 0,
    muestras: 0,
    ultimoTimestamp: null
};

// Validar fecha
const ahora = Date.parse(datos.timestamp);

if (!Number.isFinite(ahora)) {
    node.warn("KPI: timestamp no válido");
    return null;
}

// Calcular segundos transcurridos
let segundos = 0;

if (kpi.ultimoTimestamp !== null) {
    segundos = (ahora - kpi.ultimoTimestamp) / 1000;
}

// Detectar mensajes duplicados
if (segundos === 0 && kpi.ultimoTimestamp === ahora) {
    return null;
}

// Evitar intervalos negativos o excesivos
// Después de un reinicio no se contabiliza
// el tiempo durante el cual no hubo muestras
if (segundos < 0 || segundos > 5) {
    segundos = 0;
}

// Actualizar timestamp incluso si hubo reinicio
kpi.ultimoTimestamp = ahora;

// Obtener variables de la planta
const ph = Number(datos.ph);
const turbidez = Number(datos.turbidez);
const dosificacion = Number(datos.dosificacion);

const calidadCorrecta =
    Number.isFinite(ph) &&
    Number.isFinite(turbidez) &&
    ph >= 6.5 &&
    ph <= 8.5 &&
    turbidez < 5;

// 1. Volumen tratado acumulado internamente en litros
if (datos.descarga === true) {
    kpi.volumenTratado += 25 * segundos / 60;
}

// 2. Tiempo dentro de especificación
if (calidadCorrecta) {
    kpi.tiempoEspecificacion += segundos;
}

// 3. Consumo simulado de reactivo
// Dosificación al 100% = 0.1 L/min
if (Number.isFinite(dosificacion)) {
    const dosis = Math.max(0, Math.min(100, dosificacion));

    kpi.consumoReactivo +=
        (dosis / 100) * 0.1 * segundos / 60;
}

// 4. Tiempo total del proceso
kpi.tiempoProceso += segundos;

// 5. Disponibilidad operativa aproximada
if (datos.bomba === true) {
    kpi.tiempoDisponible += segundos;
}

// Contador acumulado de muestras
kpi.muestras++;

// Guardar indicadores persistentemente
context.set("kpi", kpi);

// Calcular porcentajes
const porcentajeEspecificacion =
    kpi.tiempoProceso > 0
        ? (kpi.tiempoEspecificacion /
           kpi.tiempoProceso) * 100
        : 0;

const disponibilidad =
    kpi.tiempoProceso > 0
        ? (kpi.tiempoDisponible /
           kpi.tiempoProceso) * 100
        : 0;

// Preparar salida MQTT y Debug
msg.payload = {
    dispositivo: "A09-Planta",
    timestamp: datos.timestamp,

    // Convertir litros a metros cúbicos
    volumenTratado:
        Number((kpi.volumenTratado / 1000).toFixed(4)),

    tiempoEspecificacion:
        Number(porcentajeEspecificacion.toFixed(2)),

    consumoReactivo:
        Number(kpi.consumoReactivo.toFixed(3)),

    tiempoProceso:
        Number((kpi.tiempoProceso / 60).toFixed(2)),

    disponibilidad:
        Number(disponibilidad.toFixed(2)),

    muestras: kpi.muestras
};

return msg;

let datos = msg.payload;

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        return null;
    }
}

if (!datos || !Number.isFinite(Number(datos.nivel))) {
    return null;
}

let historial = context.get("historicos") || [];

const muestra = {
    timestamp: datos.timestamp,
    nivel: Number(datos.nivel),
    caudal: Number(datos.caudal),
    ph: Number(datos.ph),
    turbidez: Number(datos.turbidez)
};

// Registrar una muestra cada 5 segundos
const ultimo = historial[historial.length - 1];

if (ultimo) {
    const diferencia =
        Date.parse(muestra.timestamp) -
        Date.parse(ultimo.timestamp);

    if (!Number.isFinite(diferencia) ||
        diferencia < 5000) {
        return null;
    }
}

historial.push(muestra);

// Mantener hasta 720 muestras (aprox. una hora)
if (historial.length > 720) {
    historial = historial.slice(-720);
}

context.set("historicos", historial);

msg.payload = {
    totalMuestras: historial.length,
    ultimaMuestra: muestra
};

return msg;
